import { type ReactNode } from "react";
import { cn } from "@/lib/cn";

// A plain container: h2 slot label, optional note directly after it, dish rows (supplied).
// The main meal is dominant by border, padding and type size. The other slots are never dimmed.

export type SlotCardProps = {
  /** Breakfast, Snack 1, Main meal or Snack 2 (a translated build supplies its own). */
  slot: string;
  slotLang?: string;
  /** "light", "lunch and dinner", "kid-facing". Follows the label immediately; not rendered when empty. */
  note?: string;
  /** Main meal. */
  dominant?: boolean;
  children: ReactNode;
  className?: string;
};

export function SlotCard({ slot, slotLang, note, dominant = false, children, className }: SlotCardProps) {
  return (
    <div
      className={cn(
        "rounded-card bg-surface-raised font-body leading-normal",
        dominant ? "border-bw-heavy border-primary-text p-card-dominant" : "border-bw-default border-border-card p-inset-md",
        className,
      )}
    >
      <h2
        lang={slotLang}
        className={cn(
          "text-ui-floor font-label [overflow-wrap:anywhere] latin:uppercase latin:tracking-label",
          dominant ? "text-primary-text" : "text-text-muted",
        )}
      >
        {slot}
      </h2>
      {note && note.trim() !== "" && <p className="text-ui-floor font-regular text-text-muted">{note}</p>}
      <div className={cn("mt-stack-sm font-medium text-text", dominant ? "text-dish-dominant" : "text-ui-body")}>{children}</div>
    </div>
  );
}
